#!/bin/sh
# /usr/local/sbin/collect-slabinfo; install root:root mode 0750.
set -eu
PATH=/usr/bin:/bin
export PATH

out=/var/log/splunk-linux-slab/slab.log
epoch=$(date +%s)
page_size=$(getconf PAGESIZE)
tmp=$(mktemp /run/slab-snapshot.XXXXXX)
trap 'rm -f "$tmp"' EXIT HUP INT TERM

awk -v epoch="$epoch" '
  $1=="MemTotal:"     { mem_total=$2*1024 }
  $1=="Slab:"         { slab=$2*1024 }
  $1=="SReclaimable:" { reclaimable=$2*1024 }
  $1=="SUnreclaim:"   { unreclaimable=$2*1024 }
  END {
    if (!mem_total || slab=="" || reclaimable=="" || unreclaimable=="") exit 2
    printf "collector_epoch=%s metric_type=summary mem_total_bytes=%.0f slab_bytes=%.0f slab_reclaimable_bytes=%.0f slab_unreclaimable_bytes=%.0f\n", epoch, mem_total, slab, reclaimable, unreclaimable
  }
' /proc/meminfo > "$tmp"

awk -v epoch="$epoch" -v page_size="$page_size" '
  $1=="slabinfo" || $1 ~ /^#/ { next }
  NF>=16 && $7==":" && $12==":" && $13=="slabdata" {
    allocated=$15*$6*page_size
    active_payload=$2*$4
    object_capacity=$3*$4
    printf "collector_epoch=%s metric_type=cache cache_name=%s active_objs=%s total_objs=%s object_size_bytes=%s objects_per_slab=%s pages_per_slab=%s active_slabs=%s total_slabs=%s page_size_bytes=%s allocated_bytes=%.0f active_object_bytes=%.0f object_capacity_bytes=%.0f\n", epoch, $1, $2, $3, $4, $5, $6, $14, $15, page_size, allocated, active_payload, object_capacity
  }
' /proc/slabinfo >> "$tmp"

cache_count=$(awk '$0 ~ /metric_type=cache/ { n++ } END { print n+0 }' "$tmp")
[ "$cache_count" -gt 0 ] || { echo "no slab cache rows parsed" >&2; exit 3; }
cat "$tmp" >> "$out"
